WITH cleaned AS (SELECT id, quantity, unit_price, CAST(quantity AS STRING) AS quantity_num FROM order_items WHERE product_id IS NOT NULL) SELECT *, FIRST_VALUE(quantity) IGNORE NULLS OVER w_grp AS first_known_quantity, FIRST_VALUE(quantity) IGNORE NULLS OVER w_grp AS first_known_quantity_2, AVG(unit_price) OVER w_recent AS unit_price_avg_2, LAST_VALUE(unit_price) IGNORE NULLS OVER w_running AS last_known_unit_price, LAG(unit_price, 2, 0) OVER (ORDER BY unit_price, id) AS prev_unit_price FROM cleaned WINDOW w_grp AS (ORDER BY unit_price, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_recent AS (ORDER BY quantity, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW), w_running AS (ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
